// Spot metal rates (LKR per gram, Colombo Sea Street spot)
export const METAL_RATES = {
  '24KT Gold': 36500,
  '22KT Gold': 33500,
  '18K Yellow Gold': 27500,
  '18K White Gold': 28200,
  '18K Rose Gold': 28000,
  '925 Sterling Silver': 950,
  'Platinum': 19500,
};

// Recursive decision tree evaluator (< 1 microsecond per tree)
function evalNode(n, x) {
  if (n.v !== undefined) return n.v;
  return x[n.f] <= n.t ? evalNode(n.l, x) : evalNode(n.r, x);
}

function predictEnsemble(trees, x) {
  if (!trees || trees.length === 0) return 0;
  let sum = 0;
  for (let i = 0; i < trees.length; i++) {
    sum += evalNode(trees[i], x);
  }
  return sum;
}

/**
 * Calculates physical Bill of Materials (BOM) in Sri Lankan Rupees (LKR).
 */
export function calculateBOM(spec) {
  const metalWeight = Number(spec.metal_weight_g || 5.0);
  const gemWeight = Number(spec.gemstone_weight_ct || 2.5);
  const accents = Number(spec.number_of_accent_stones || 0);

  // 1. Precious Metal Cost with 10% casting wastage
  const rate = METAL_RATES[spec.metal] || 33500;
  const metalCost = metalWeight * rate * 1.10;

  // 2. Empirical Ceylon Sapphire Pricing Curve: Price = 385,076 * (carats)^1.28
  const baseGem = 385076 * Math.pow(gemWeight, 1.28);
  const gradeMul = spec.stone_grade && spec.stone_grade.includes('AAA')
    ? 1.45
    : spec.stone_grade && spec.stone_grade.includes('AA')
    ? 1.00
    : 0.75;
  const gemCost = baseGem * gradeMul;

  // 3. Shop Owner Verified Labor Matrix (Wadakuliya)
  const category = spec.category || 'Ring';
  const labor = category === 'Necklace' ? 13500 : category === 'Earring' ? 4500 : 4000;
  const settingCost = (accents + 1) * 800;
  const accentCost = accents * 4200;

  const totalMfgCost = metalCost + gemCost + labor + settingCost + accentCost;

  return {
    metal_cost_lkr: Math.round(metalCost),
    gemstone_cost_lkr: Math.round(gemCost),
    labor_cost_lkr: Math.round(labor),
    setting_cost_lkr: Math.round(settingCost),
    accent_cost_lkr: Math.round(accentCost),
    total_manufacturing_cost_lkr: Math.round(totalMfgCost),
  };
}

/**
 * Executes full on-device appraisal returning BOM and P10/P50/P90 market spreads.
 */
export function evaluateOnDeviceValuation(spec) {
  const bom = calculateBOM(spec);

  // Features aligned with training: [total_mfg_cost, gem_cost, metal_cost, carats, grams, accents]
  const features = [
    bom.total_manufacturing_cost_lkr,
    bom.gemstone_cost_lkr,
    bom.metal_cost_lkr,
    Number(spec.gemstone_weight_ct || 2.5),
    Number(spec.metal_weight_g || 5.0),
    Number(spec.number_of_accent_stones || 0),
  ];

  // Evaluate Champion LightGBM Trees
  let p50 = predictEnsemble(TREES_P50, features);
  let p10 = predictEnsemble(TREES_P10, features);
  let p90 = predictEnsemble(TREES_P90, features);

  // Anchor to physical BOM floors
  if (p10 <= 0 || p10 < bom.total_manufacturing_cost_lkr) {
    p10 = bom.total_manufacturing_cost_lkr * 1.06;
  }
  if (p50 <= 0 || p50 < p10) {
    p50 = bom.total_manufacturing_cost_lkr * 1.18;
  }
  if (p90 <= 0 || p90 < p50) {
    p90 = bom.total_manufacturing_cost_lkr * 1.38;
  }

  return {
    bom_breakdown: bom,
    valuation: {
      p10_wholesale_floor_lkr: Math.round(p10),
      p50_fair_market_price_lkr: Math.round(p50),
      p90_showroom_ceiling_lkr: Math.round(p90),
    },
    source: 'on_device_lightgbm',
  };
}

export default {
  calculateBOM,
  evaluateOnDeviceValuation,
  METAL_RATES,
};
